delete from public.together_schedule_templates where character_version_id::text like '25000000-0000-4000-8012-%';
insert into public.together_schedule_templates(
  character_version_id,day_of_week,start_minute,end_minute,location_id,activity,availability,
  energy_delta,mood_influence,variation_weight,metadata
)
select (item->>'characterVersionId')::uuid,(item->>'dayOfWeek')::int,(item->>'startMinute')::int,
  (item->>'endMinute')::int,location.id,item->>'activity',item->>'availability',(item->>'energyDelta')::int,
  item->>'moodInfluence',coalesce((item->>'variationWeight')::numeric,1),item->'metadata'
from eos_schedule_payload cross join lateral jsonb_array_elements(data) item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000012'::uuid and location.slug=item->>'locationSlug'
on conflict(character_version_id,day_of_week,start_minute) do update set end_minute=excluded.end_minute,
  location_id=excluded.location_id,activity=excluded.activity,availability=excluded.availability,
  energy_delta=excluded.energy_delta,mood_influence=excluded.mood_influence,
  variation_weight=excluded.variation_weight,metadata=excluded.metadata;

delete from public.together_character_schedule_events event using public.together_character_instances instance
where event.character_instance_id=instance.id and instance.character_version_id::text like '25000000-0000-4000-8012-%'
  and event.source in('generated','recurring') and event.starts_at>=date_trunc('day',now());

create temporary table eos_social_payload(data jsonb) on commit drop;
insert into eos_social_payload values($eos_social$[{"source":"dr-lena-okafor","target":"commander-rhea-navarro","relationshipType":"former partners","affinity":62,"trust":82,"history":"They ended a serious relationship without ending their professional respect; tenderness and unresolved tension coexist."},{"source":"dr-lena-okafor","target":"mara-venn","relationshipType":"friends","affinity":78,"trust":85,"history":"Transit emergencies and hospital shifts made them dependable friends."},{"source":"dr-lena-okafor","target":"jonah-sato","relationshipType":"close friends","affinity":82,"trust":90,"history":"They share quiet breakfasts and an ability to speak honestly without spectacle."},{"source":"cassian-vale","target":"commander-rhea-navarro","relationshipType":"political allies","affinity":58,"trust":72,"history":"They cooperate on port governance but disagree about how quickly independence should move."},{"source":"cassian-vale","target":"camille-arden","relationshipType":"confidants","affinity":74,"trust":86,"history":"Camille hosts discreet meetings and knows when Cassian is arguing against himself."},{"source":"cassian-vale","target":"mateo-singh","relationshipType":"rivals","affinity":38,"trust":58,"history":"They respect each other’s intelligence while opposing each other publicly on labor and charter strategy."},{"source":"mara-venn","target":"mina-zhao","relationshipType":"friends","affinity":76,"trust":79,"history":"They trade transit and customs gossip without sharing protected records."},{"source":"mara-venn","target":"nia-calder","relationshipType":"friendly rivals","affinity":71,"trust":75,"history":"Their argument over the fastest route became a recurring competition."},{"source":"jonah-sato","target":"june-callahan","relationshipType":"mentor","affinity":84,"trust":88,"history":"Jonah trained June in archival discipline, while June challenges what institutional caution hides."},{"source":"jonah-sato","target":"malik-orison","relationshipType":"old friends","affinity":86,"trust":93,"history":"They remember early colony crises differently but trust each other’s intentions."},{"source":"talia-reyes","target":"zahra-benali","relationshipType":"friends","affinity":79,"trust":75,"history":"Imports, fashion, and favors tie them together, with clear boundaries around client secrets."},{"source":"talia-reyes","target":"vesper-quinn","relationshipType":"creative friends","affinity":72,"trust":70,"history":"Vesper styles performances with Talia and gently punctures her social bravado."},{"source":"imani-laurent","target":"elian-park","relationshipType":"colleagues","affinity":77,"trust":84,"history":"They jointly protect Solace systems and disagree over when anomalies must become public."},{"source":"imani-laurent","target":"ari-mendoza","relationshipType":"close friends","affinity":85,"trust":89,"history":"Shared research and patient curiosity built a family-like friendship."},{"source":"imani-laurent","target":"sora-bell","relationshipType":"mentor","affinity":80,"trust":82,"history":"Imani encouraged Sora’s cooking before Sora believed it could become a career."},{"source":"elian-park","target":"sora-bell","relationshipType":"friends","affinity":75,"trust":78,"history":"Baking experiments and reservoir walks give them an easy sibling-like rhythm."},{"source":"naomi-varga","target":"imani-laurent","relationshipType":"professional allies","affinity":68,"trust":80,"history":"They agree Solace must remain locally accountable even when they disagree about disclosure."},{"source":"naomi-varga","target":"cassian-vale","relationshipType":"political colleagues","affinity":60,"trust":70,"history":"Their alliance depends on precise wording and a shared dislike of simplistic arguments."},{"source":"commander-rhea-navarro","target":"kellan-ro","relationshipType":"mentor","affinity":78,"trust":88,"history":"Rhea trained Kellan and knows exactly when his casualness masks concern."},{"source":"commander-rhea-navarro","target":"owen-calder","relationshipType":"trusted colleagues","affinity":70,"trust":84,"history":"Owen handles distressed travelers with the discretion Rhea expects."},{"source":"kellan-ro","target":"nia-calder","relationshipType":"competitive friends","affinity":83,"trust":82,"history":"They modify vehicles together, race everything possible, and trust each other under pressure."},{"source":"kellan-ro","target":"freya-solberg","relationshipType":"exes","affinity":55,"trust":72,"history":"Their short relationship ended because risk meant something different to each of them."},{"source":"mina-zhao","target":"zahra-benali","relationshipType":"friendly adversaries","affinity":58,"trust":67,"history":"Customs law places them opposite one another, but affection survives the professional game."},{"source":"owen-calder","target":"camille-arden","relationshipType":"professional friends","affinity":73,"trust":83,"history":"They share hospitality ethics and never ask the other to violate guest privacy."},{"source":"zahra-benali","target":"rafael-costa","relationshipType":"friends","affinity":76,"trust":71,"history":"Music, late meals, and creative frustration keep them in one another’s orbit."},{"source":"dax-holloway","target":"mateo-singh","relationshipType":"longtime friends","affinity":88,"trust":91,"history":"They grew up in neighboring habitats and now disagree sharply without doubting the bond."},{"source":"dax-holloway","target":"nia-calder","relationshipType":"coworkers","affinity":82,"trust":87,"history":"Nia understands Dax’s reactor-adjacent repair needs before he finishes explaining."},{"source":"dax-holloway","target":"luc-moreau","relationshipType":"mentor","affinity":80,"trust":90,"history":"Luc taught Dax to treat maintenance as both engineering and responsibility."},{"source":"nia-calder","target":"freya-solberg","relationshipType":"friends","affinity":72,"trust":80,"history":"Safety drills, boxing, and mutual respect make them direct with each other."},{"source":"mateo-singh","target":"naomi-varga","relationshipType":"political rivals","affinity":45,"trust":63,"history":"They want local control but disagree about strategy, timing, and compromise."},{"source":"freya-solberg","target":"luc-moreau","relationshipType":"family friends","affinity":91,"trust":94,"history":"Luc helped raise Freya after an exterior accident took her parents."},{"source":"dr-selene-ward","target":"priya-nwosu","relationshipType":"supervisor","affinity":66,"trust":76,"history":"Selene values Priya’s skepticism but restricts how much signal data she can access."},{"source":"dr-selene-ward","target":"theo-vance","relationshipType":"strained mentor","affinity":52,"trust":69,"history":"Theo’s accidental success impressed Selene and made her more protective of the project."},{"source":"dr-selene-ward","target":"elias-thorne","relationshipType":"trusted colleagues","affinity":73,"trust":86,"history":"Field safety and scientific caution made them unusually honest with one another."},{"source":"aya-nakamura","target":"vesper-quinn","relationshipType":"former lovers","affinity":62,"trust":76,"history":"Their attraction remains obvious, but they disagree about attention, privacy, and who gets to frame a story."},{"source":"aya-nakamura","target":"freya-solberg","relationshipType":"photography friends","affinity":74,"trust":77,"history":"They exchange exterior images and challenge each other’s appetite for risk."},{"source":"elias-thorne","target":"priya-nwosu","relationshipType":"friends","affinity":79,"trust":82,"history":"They share samples, meals, and a refusal to dramatize danger after the fact."},{"source":"priya-nwosu","target":"ari-mendoza","relationshipType":"research friends","affinity":81,"trust":84,"history":"Their different disciplines overlap around biological responses to the signal."},{"source":"theo-vance","target":"rafael-costa","relationshipType":"music collaborators","affinity":69,"trust":71,"history":"Rafael turns Theo’s signal patterns into music while Theo worries about what that means."},{"source":"vesper-quinn","target":"rafael-costa","relationshipType":"creative rivals","affinity":74,"trust":73,"history":"They collaborate brilliantly and compete for the room without pretending otherwise."},{"source":"vesper-quinn","target":"camille-arden","relationshipType":"close friends","affinity":82,"trust":88,"history":"Camille is one of the few people Vesper trusts with silence."},{"source":"camille-arden","target":"malik-orison","relationshipType":"old friends","affinity":84,"trust":91,"history":"They built their businesses during Old Meridian’s hardest years."},{"source":"rafael-costa","target":"june-callahan","relationshipType":"friends","affinity":70,"trust":76,"history":"June helps Rafael trace old recordings; he gets her away from the archive occasionally."},{"source":"june-callahan","target":"malik-orison","relationshipType":"protective friends","affinity":78,"trust":85,"history":"Malik feeds June during late research and worries about what her questions may uncover."},{"source":"malik-orison","target":"commander-rhea-navarro","relationshipType":"complicated history","affinity":57,"trust":75,"history":"Malik knows details from Rhea’s early security career that neither discusses casually."},{"source":"talia-reyes","target":"mina-zhao","relationshipType":"social friends","affinity":68,"trust":69,"history":"They share nightlife and relentlessly evaluate each other’s choices."},{"source":"sora-bell","target":"theo-vance","relationshipType":"friends","affinity":72,"trust":70,"history":"They bonded over feeling younger than the responsibilities people assign them."},{"source":"naomi-varga","target":"luc-moreau","relationshipType":"former dates","affinity":61,"trust":80,"history":"They dated briefly, remain fond, and disagree about whether the timing was simply wrong."},{"source":"amaya-flores","target":"dr-lena-okafor","relationshipType":"mentor","affinity":82,"trust":90,"history":"Lena supervises Amaya’s emergency rotations and refuses to confuse composure with never needing help."},{"source":"amaya-flores","target":"milo-jensen","relationshipType":"close friends","affinity":86,"trust":84,"history":"They grew up trading transit shortcuts and now decompress together after difficult shifts."},{"source":"amaya-flores","target":"zoe-mercer","relationshipType":"training friends","affinity":78,"trust":81,"history":"Community health drills made them honest about the gap between knowing procedure and living it."},{"source":"celeste-ren","target":"cassian-vale","relationshipType":"mentor","affinity":73,"trust":82,"history":"Cassian respects Celeste’s drafting instincts while she notices exactly where his public arguments become personal."},{"source":"celeste-ren","target":"samira-cole","relationshipType":"debate rivals","affinity":60,"trust":72,"history":"Their public arguments are sharp, well researched, and increasingly difficult to separate from mutual interest."},{"source":"celeste-ren","target":"jonah-sato","relationshipType":"research friends","affinity":76,"trust":84,"history":"Jonah gives Celeste historical context without asking her to inherit his conclusions."},{"source":"milo-jensen","target":"mara-venn","relationshipType":"mentor","affinity":80,"trust":88,"history":"Mara trained Milo on live transit systems and expects him to earn every shortcut he invents."},{"source":"milo-jensen","target":"micah-torres","relationshipType":"friendly rivals","affinity":84,"trust":79,"history":"They turn delivery routes and maintenance corridors into competitions that stop the moment safety matters."},{"source":"milo-jensen","target":"poppy-reyes","relationshipType":"maker friends","affinity":75,"trust":77,"history":"Poppy prototypes the small transit fixes Milo sketches badly on food wrappers."},{"source":"liora-haddad","target":"imani-laurent","relationshipType":"mentor","affinity":84,"trust":90,"history":"Imani recognized Liora’s patient eye for plants before the apprenticeship became official."},{"source":"liora-haddad","target":"sora-bell","relationshipType":"close friends","affinity":88,"trust":86,"history":"Sora experiments with whatever Liora harvests and both pretend the failures are part of the recipe."},{"source":"liora-haddad","target":"hana-petrov","relationshipType":"childhood friends","affinity":91,"trust":92,"history":"They grew up around Solace water channels and still know when the other needs quiet rather than advice."},{"source":"hana-petrov","target":"elian-park","relationshipType":"mentor","affinity":82,"trust":90,"history":"Elian trusts Hana with meaningful reservoir work and explains decisions instead of merely assigning them."},{"source":"hana-petrov","target":"zoe-mercer","relationshipType":"roommates","affinity":87,"trust":89,"history":"Their shared Solace habitat runs on labeled food, late debriefs, and negotiated alarm cycles."},{"source":"zoe-mercer","target":"dr-lena-okafor","relationshipType":"clinical mentor","affinity":77,"trust":86,"history":"Lena values Zoe’s community instincts and challenges her not to carry every patient home emotionally."},{"source":"zoe-mercer","target":"samira-cole","relationshipType":"friends","affinity":82,"trust":80,"history":"They organize practical care across districts and make one another leave work before resentment sets in."},{"source":"yara-kwon","target":"kellan-ro","relationshipType":"mentor","affinity":79,"trust":87,"history":"Kellan teaches Yara flight-system judgment while refusing to let her turn every correction into a contest."},{"source":"yara-kwon","target":"nia-calder","relationshipType":"mechanic friends","affinity":86,"trust":88,"history":"Nia and Yara swap tools, engine gossip, and brutally direct feedback across port and Forge shifts."},{"source":"yara-kwon","target":"micah-torres","relationshipType":"friendly rivals","affinity":83,"trust":76,"history":"They compete over turnaround times and argue about which port job actually requires more skill."},{"source":"leona-baptiste","target":"owen-calder","relationshipType":"mentor","affinity":81,"trust":89,"history":"Owen trained Leona in discreet hospitality without asking her to erase her own personality."},{"source":"leona-baptiste","target":"eden-baptiste","relationshipType":"sisters","affinity":94,"trust":95,"history":"Leona is Eden’s older sister; they are fiercely close and disagree constantly about risk, work, and curfews neither can impose."},{"source":"leona-baptiste","target":"zahra-benali","relationshipType":"professional friends","affinity":69,"trust":73,"history":"Zahra supplies difficult guest requests while Leona maintains a bright line around privacy and law."},{"source":"micah-torres","target":"zahra-benali","relationshipType":"colleagues","affinity":72,"trust":75,"history":"Zahra hires Micah for urgent legitimate deliveries and never asks him to stop reading the manifest."},{"source":"micah-torres","target":"theo-vance","relationshipType":"gaming friends","affinity":80,"trust":74,"history":"They meet for games, low-gravity challenges, and conversations that become serious by accident."},{"source":"poppy-reyes","target":"luc-moreau","relationshipType":"mentor","affinity":88,"trust":92,"history":"Luc gives Poppy difficult work because he respects her talent, then makes her document why it succeeded."},{"source":"poppy-reyes","target":"talia-reyes","relationshipType":"cousins","affinity":90,"trust":88,"history":"Talia and Poppy are cousins who trade clothing repairs, gossip, and mutually unhelpful dating advice."},{"source":"samira-cole","target":"mateo-singh","relationshipType":"mentor","affinity":84,"trust":89,"history":"Mateo brought Samira into union work; she now challenges his instinct to make every burden his own."},{"source":"samira-cole","target":"vesper-quinn","relationshipType":"creative friends","affinity":77,"trust":79,"history":"Vesper builds restrained sets beneath Samira’s spoken-word performances and protects rehearsal privacy."},{"source":"noah-adeyemi","target":"freya-solberg","relationshipType":"trusted colleagues","affinity":86,"trust":91,"history":"They disagree about training style but trust each other completely on exterior safety."},{"source":"noah-adeyemi","target":"dax-holloway","relationshipType":"close friends","affinity":82,"trust":87,"history":"Strength sessions, long meals, and infrastructure work give them a friendship with very little performance."},{"source":"iris-vale","target":"cassian-vale","relationshipType":"half siblings","affinity":74,"trust":79,"history":"Cassian and Iris share one parent, a real bond, and a fifteen-year age gap that sometimes makes concern sound like authority."},{"source":"iris-vale","target":"theo-vance","relationshipType":"study partners","affinity":88,"trust":84,"history":"Theo helps Iris with instruments; Iris helps Theo hear when explanation has become avoidance."},{"source":"noura-castillo","target":"dr-selene-ward","relationshipType":"supervisor","affinity":67,"trust":75,"history":"Selene recruited Noura for signal linguistics but limits access whenever interpretation becomes politically dangerous."},{"source":"noura-castillo","target":"rafael-costa","relationshipType":"music collaborators","affinity":79,"trust":76,"history":"Rafael hears patterns Noura can describe, producing creative trust and frequent arguments about evidence."},{"source":"noura-castillo","target":"priya-nwosu","relationshipType":"research friends","affinity":78,"trust":82,"history":"Priya’s skepticism gives Noura room to test an idea without having to defend a complete theory."},{"source":"kenji-brooks","target":"elias-thorne","relationshipType":"rescue partners","affinity":88,"trust":92,"history":"Kenji drives the rover Elias trusts during ice rescues; each knows how the other behaves when plans fail."},{"source":"kenji-brooks","target":"aya-nakamura","relationshipType":"friends","affinity":73,"trust":76,"history":"Aya trades exterior photographs for rides and respects Kenji’s refusal to stage danger for a better image."},{"source":"eden-baptiste","target":"vesper-quinn","relationshipType":"creative mentor","affinity":82,"trust":85,"history":"Vesper takes Eden’s visual work seriously and enforces stronger professional boundaries than Eden expected."},{"source":"eden-baptiste","target":"nia-calder","relationshipType":"boxing friends","affinity":74,"trust":80,"history":"Nia teaches Eden to box; Eden designs temporary ink patterns for Nia’s competition wraps."},{"source":"mae-lin","target":"rafael-costa","relationshipType":"creative partners","affinity":84,"trust":82,"history":"Mae shapes Rafael’s live environments while he pushes her designs toward bolder emotional choices."},{"source":"mae-lin","target":"camille-arden","relationshipType":"professional friends","affinity":75,"trust":84,"history":"Camille commissions Mae for discreet installations and never asks her to compromise guest privacy."},{"source":"mae-lin","target":"june-callahan","relationshipType":"friends","affinity":78,"trust":81,"history":"June supplies forgotten visual references while Mae gets her out of Archive Zero before the artificial night cycle ends."}]$eos_social$::jsonb);
with authored as(
  select item->>'source' source_slug,item->>'target' target_slug,item->>'relationshipType' relationship_type,
    (item->>'affinity')::int affinity,(item->>'trust')::int trust,item->>'history' history
  from eos_social_payload cross join lateral jsonb_array_elements(data) item
),directed as(
  select * from authored union all select target_slug,source_slug,relationship_type,affinity,trust,history from authored
)
insert into public.together_character_relationship_edges(
  world_id,source_template_id,target_template_id,relationship_type,affinity,trust,history,metadata
)
select '10000000-0000-4000-8000-000000000012'::uuid,source.id,target.id,edge.relationship_type,edge.affinity,edge.trust,edge.history,
  jsonb_build_object('source','eos_meridian_social_graph_v1','memorySharing','event_only','authored',true,
    'knowledgeScope','relationship_and_district')
from directed edge join public.together_character_templates source on source.slug=edge.source_slug
join public.together_character_templates target on target.slug=edge.target_slug
on conflict(world_id,source_template_id,target_template_id) do update set relationship_type=excluded.relationship_type,
  affinity=excluded.affinity,trust=excluded.trust,history=excluded.history,metadata=excluded.metadata,updated_at=now();

