insert into public.together_character_place_profiles(
  character_version_id,location_id,familiarity,sentiment,confidence,opinion_summary,opinion_tags,
  preferred_activities,favorite_details,disliked_details,metadata
)
select (item->>'versionId')::uuid,location.id,.95,.58,.92,
  (item->>'name')||' knows '||location.name||' through ordinary routine and has an occupation-specific point of view rather than generic world knowledge.',
  array['routine','work','eos-meridian'],array(
    select interest.value
    from jsonb_array_elements_text(item->'interests') with ordinality as interest(value,ordinality)
    where interest.ordinality<=2
    order by interest.ordinality
  ),
  array['repeat routines','competent staff'],array['avoidable access violations'],jsonb_build_object('source','eos_meridian_content_v1','knowledgeScope','direct')
from eos_character_payload cross join lateral jsonb_array_elements(data) item
join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000012'::uuid and location.slug=item->>'workSlug'
on conflict(character_version_id,location_id) do update set familiarity=excluded.familiarity,sentiment=excluded.sentiment,
  confidence=excluded.confidence,opinion_summary=excluded.opinion_summary,opinion_tags=excluded.opinion_tags,
  preferred_activities=excluded.preferred_activities,favorite_details=excluded.favorite_details,
  disliked_details=excluded.disliked_details,metadata=excluded.metadata,updated_at=now();

create temporary table eos_event_payload(data jsonb) on commit drop;
insert into eos_event_payload values($eos_events$[{"name":"Docking Day","eventType":"community_arrival","locationSlug":"ascension-terminal","participantSlugs":["commander-rhea-navarro","kellan-ro","mina-zhao","owen-calder","zahra-benali","yara-kwon","leona-baptiste","micah-torres"],"category":"social","tone":"positive","probability":0.72,"durationMinutes":180,"recurrence":{"weekday":5,"startMinute":1020},"summary":"A major passenger and cargo arrival brings reunions, departures, scarce imports, and fresh colony gossip into the port."},{"name":"Artificial Rain","eventType":"solace_rain_cycle","locationSlug":"rain-room","participantSlugs":["imani-laurent","elian-park","sora-bell","ari-mendoza","liora-haddad","hana-petrov","zoe-mercer"],"category":"environment","tone":"romantic","probability":0.7,"durationMinutes":90,"recurrence":{"weekday":6,"startMinute":900},"summary":"Solace opens a public rain cycle, drawing residents into a warm sensory ritual that naturally slows conversation."},{"name":"Black Sky Night","eventType":"aurora_blackout","locationSlug":"eventide-overlook","participantSlugs":["dr-selene-ward","aya-nakamura","elias-thorne","priya-nwosu","theo-vance","iris-vale","noura-castillo","kenji-brooks"],"category":"environment","tone":"intimate","probability":0.45,"durationMinutes":120,"recurrence":{"weekday":6,"startMinute":1200},"summary":"The colony dims nonessential exterior lights so the aurora and night horizon become unusually vivid."},{"name":"Low-G Night","eventType":"nightlife","locationSlug":"velvet-gravity","participantSlugs":["vesper-quinn","talia-reyes","aya-nakamura","mina-zhao","rafael-costa","micah-torres","eden-baptiste","mae-lin"],"category":"music","tone":"playful","probability":0.78,"durationMinutes":240,"recurrence":{"weekday":5,"startMinute":1260},"summary":"Velvet Gravity lowers the dance floor field for a carefully controlled night of movement, music, and interjections."},{"name":"Forge Assembly","eventType":"civic_labor","locationSlug":"forge-union-hall","participantSlugs":["mateo-singh","dax-holloway","nia-calder","luc-moreau","cassian-vale","poppy-reyes","samira-cole","noah-adeyemi"],"category":"community","tone":"grounded","probability":0.58,"durationMinutes":120,"recurrence":{"weekday":3,"startMinute":1080},"summary":"A public labor and independence meeting turns practical infrastructure questions into personal disagreements."},{"name":"The Long Table","eventType":"community_meal","locationSlug":"hearth-kitchens","participantSlugs":["sora-bell","imani-laurent","elian-park","jonah-sato","malik-orison","liora-haddad","zoe-mercer","samira-cole"],"category":"community","tone":"positive","probability":0.62,"durationMinutes":150,"recurrence":{"weekday":0,"startMinute":1020},"summary":"A communal meal invites different districts to share food, repeat traditions, and notice who sits beside whom."},{"name":"Red Storm Lockdown","eventType":"weather_lockdown","locationSlug":"meridian-concourse","participantSlugs":["mara-venn","dr-lena-okafor","cassian-vale","talia-reyes","amaya-flores","celeste-ren","milo-jensen"],"category":"weather","tone":"tense","probability":0.18,"durationMinutes":180,"recurrence":{"random":true,"dayparts":["afternoon","evening"]},"summary":"An electrical dust storm closes exterior transit and forces plans, shifts, and conversations into shared shelter."},{"name":"Signal Window","eventType":"signal_peak","locationSlug":"listening-station-seven","participantSlugs":["dr-selene-ward","priya-nwosu","theo-vance","aya-nakamura","iris-vale","noura-castillo","kenji-brooks"],"category":"mystery","tone":"tense","probability":0.16,"durationMinutes":75,"recurrence":{"random":true,"dayparts":["late_night"]},"summary":"The buried transmission strengthens briefly, affecting instruments and drawing prepared researchers toward Nightglass."}]$eos_events$::jsonb);
insert into public.together_event_templates(
  id,name,event_type,world_id,default_location_id,participant_template_ids,significance,probability,
  duration_minutes,narrative_summary,state_effects,user_visibility,proactive_eligible,metadata,active,
  category,tone,scale,content_level,conditions,followups
)
select ('3b000000-0000-4000-8012-'||lpad(ordinality::text,12,'0'))::uuid,item->>'name',item->>'eventType',
  '10000000-0000-4000-8000-000000000012'::uuid,location.id,array(select template.id from public.together_character_templates template
    where template.slug=any(array(select jsonb_array_elements_text(item->'participantSlugs')))),
  .58,(item->>'probability')::numeric,(item->>'durationMinutes')::int,item->>'summary','{}'::jsonb,'contextual',true,
  jsonb_build_object('worldSlug','eos-meridian','worldEvent',true,'recurrence',item->'recurrence','scheduleAware',true,'userLocalClock',true),true,
  case item->>'category' when 'music' then 'social' when 'environment' then 'world' when 'community' then 'social' when 'mystery' then 'discovery' else item->>'category' end,
  case item->>'tone' when 'grounded' then 'positive' when 'intimate' then 'romantic' when 'tense' then 'surprising' when 'playful' then 'exciting' else item->>'tone' end,
  'normal','standard',jsonb_build_object('recurrence',item->'recurrence'),'{}'::text[]
from eos_event_payload cross join lateral jsonb_array_elements(data) with ordinality payload(item,ordinality)
join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000012'::uuid and location.slug=item->>'locationSlug'
on conflict(id) do update set name=excluded.name,event_type=excluded.event_type,default_location_id=excluded.default_location_id,
  participant_template_ids=excluded.participant_template_ids,probability=excluded.probability,duration_minutes=excluded.duration_minutes,
  narrative_summary=excluded.narrative_summary,metadata=excluded.metadata,conditions=excluded.conditions,active=true,updated_at=now();

create temporary table eos_story_payload(data jsonb) on commit drop;
insert into eos_story_payload values($eos_stories$[{"slug":"eos-missing-seventeen-hours","title":"The Seventeen Missing Hours","category":"mystery","leadSlugs":["june-callahan","jonah-sato","malik-orison","commander-rhea-navarro","celeste-ren","eden-baptiste"],"locationSlugs":["archive-zero","pioneer-memorial","first-habitat"],"minStage":"friend","premise":"Personal records and official exhibits disagree about what happened immediately after the first landing.","chapters":[{"title":"An inconsistency","narrativeSeed":"A small, credible inconsistency opens personal records and official exhibits disagree about what happened immediately after the first landing."},{"title":"The human cost","narrativeSeed":"The mystery intersects with work, loyalty, and a relationship rather than remaining abstract lore."},{"title":"A bounded choice","narrativeSeed":"The user and companion face a meaningful choice without the story forcing a permanent world outcome."}]},{"slug":"eos-beneath-night-ice","title":"Beneath the Night Ice","category":"mystery","leadSlugs":["dr-selene-ward","priya-nwosu","elias-thorne","aya-nakamura","theo-vance","iris-vale","noura-castillo","kenji-brooks"],"locationSlugs":["listening-station-seven","black-lake","farline-laboratory"],"minStage":"acquaintance","premise":"The signal, a warm cavity, and biological responses suggest the night ice holds something the colony has not explained.","chapters":[{"title":"An inconsistency","narrativeSeed":"A small, credible inconsistency opens the signal, a warm cavity, and biological responses suggest the night ice holds something the colony has not explained."},{"title":"The human cost","narrativeSeed":"The mystery intersects with work, loyalty, and a relationship rather than remaining abstract lore."},{"title":"A bounded choice","narrativeSeed":"The user and companion face a meaningful choice without the story forcing a permanent world outcome."}]},{"slug":"eos-independence-vote","title":"The Charter Choice","category":"politics","leadSlugs":["cassian-vale","mateo-singh","dax-holloway","naomi-varga","zahra-benali","celeste-ren","samira-cole"],"locationSlugs":["charter-hall","forge-union-hall","caldera-reactor"],"minStage":"acquaintance","premise":"Competing but credible visions of independence force residents to decide what risk and ownership mean.","chapters":[{"title":"An inconsistency","narrativeSeed":"A small, credible inconsistency opens competing but credible visions of independence force residents to decide what risk and ownership mean."},{"title":"The human cost","narrativeSeed":"The mystery intersects with work, loyalty, and a relationship rather than remaining abstract lore."},{"title":"A bounded choice","narrativeSeed":"The user and companion face a meaningful choice without the story forcing a permanent world outcome."}]},{"slug":"eos-habitat-lyra","title":"Habitat Lyra","category":"discovery","leadSlugs":["kellan-ro","nia-calder","freya-solberg","luc-moreau","milo-jensen","poppy-reyes","mae-lin"],"locationSlugs":["hangar-twelve","redline-garage","ghost-junction"],"minStage":"friend","premise":"An abandoned habitat transmits valid credentials and appears connected to a route missing from current maps.","chapters":[{"title":"An inconsistency","narrativeSeed":"A small, credible inconsistency opens an abandoned habitat transmits valid credentials and appears connected to a route missing from current maps."},{"title":"The human cost","narrativeSeed":"The mystery intersects with work, loyalty, and a relationship rather than remaining abstract lore."},{"title":"A bounded choice","narrativeSeed":"The user and companion face a meaningful choice without the story forcing a permanent world outcome."}]},{"slug":"eos-solace-bloom","title":"The Solace Bloom","category":"discovery","leadSlugs":["imani-laurent","elian-park","ari-mendoza","sora-bell","liora-haddad","hana-petrov","zoe-mercer"],"locationSlugs":["pollinator-house","solace-reservoir","orchard-nine"],"minStage":"friend","premise":"Uncultivated plants and coordinated pollinator behavior turn a biological anomaly into a choice about disclosure.","chapters":[{"title":"An inconsistency","narrativeSeed":"A small, credible inconsistency opens uncultivated plants and coordinated pollinator behavior turn a biological anomaly into a choice about disclosure."},{"title":"The human cost","narrativeSeed":"The mystery intersects with work, loyalty, and a relationship rather than remaining abstract lore."},{"title":"A bounded choice","narrativeSeed":"The user and companion face a meaningful choice without the story forcing a permanent world outcome."}]},{"slug":"eos-ghost-passenger","title":"The Ghost Passenger","category":"mystery","leadSlugs":["owen-calder","mina-zhao","camille-arden","commander-rhea-navarro","leona-baptiste","micah-torres"],"locationSlugs":["wayfarer-hotel","customs-hall","quiet-orbit"],"minStage":"flirting","premise":"Someone is traveling through the colony using the identities of people recorded as dead.","chapters":[{"title":"An inconsistency","narrativeSeed":"A small, credible inconsistency opens someone is traveling through the colony using the identities of people recorded as dead."},{"title":"The human cost","narrativeSeed":"The mystery intersects with work, loyalty, and a relationship rather than remaining abstract lore."},{"title":"A bounded choice","narrativeSeed":"The user and companion face a meaningful choice without the story forcing a permanent world outcome."}]}]$eos_stories$::jsonb);
insert into public.together_story_arc_templates(
  slug,title,category,eligible_template_ids,min_relationship_stage,prerequisites,chapters,
  cooldown_days,repeatable,priority,active,world_scope,specific_world_id
)
select item->>'slug',item->>'title',item->>'category',
  array(select template.id from public.together_character_templates template
    where template.slug=any(array(select jsonb_array_elements_text(item->'leadSlugs')))),item->>'minStage',
  jsonb_build_object('worldSlug','eos-meridian','characterSlugs',item->'leadSlugs','locationSlugs',item->'locationSlugs',
    'dialogueDriven',true,'requiresCorrectPlaceWhenAdvancing',true,'premise',item->>'premise'),
  (select jsonb_agg(jsonb_build_object('id','chapter-'||ordinality,'title',chapter->>'title',
    'userVisibility',case when ordinality=1 then 'contextual' else 'visible' end,'mayTriggerProactiveMessage',true,
    'mayCreateMoment',ordinality=jsonb_array_length(item->'chapters'),'narrativeSeed',chapter->>'narrativeSeed',
    'minimumHoursBeforeNext',case when ordinality=1 then 12 else 24 end,
    'eligibleCharacterSlugs',item->'leadSlugs','eligibleLocationSlugs',item->'locationSlugs') order by ordinality)
    from jsonb_array_elements(item->'chapters') with ordinality chapter_rows(chapter,ordinality)),
  90,false,'major',true,'specific','10000000-0000-4000-8000-000000000012'::uuid
from eos_story_payload cross join lateral jsonb_array_elements(data) item
on conflict(slug) do update set title=excluded.title,category=excluded.category,
