  prerequisites=excluded.prerequisites,chapters=excluded.chapters,world_scope='specific',
  specific_world_id=excluded.specific_world_id,active=true,updated_at=now();

create temporary table eos_fact_payload(data jsonb) on commit drop;
insert into eos_fact_payload values($eos_facts$[{"slug":"eos-charter-transfer","title":"The Charter Transfer","category":"law","fact":"The Founding Charter requires Axiom to offer local purchase of essential infrastructure once audited maintenance and reserve thresholds are met.","triggerTerms":["charter","independence","axiom"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-air-is-public","title":"Air Is a Public Utility","category":"law","fact":"Tampering with shared atmosphere, pressure integrity, water, or emergency power is treated as a severe public-safety crime rather than property damage.","triggerTerms":["air","pressure","sabotage"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-privacy-standard","title":"Habitat Privacy Standard","category":"privacy","fact":"Private rooms and discreet venues must disclose sensing and recording systems; hidden intimate recording is illegal throughout Meridian.","triggerTerms":["privacy","recording","room"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-spoken-consent","title":"Spoken Withdrawal Controls","category":"adult","fact":"No digital authorization, venue handshake, or prior agreement overrides a present spoken or physical withdrawal of consent.","triggerTerms":["consent","venue","adult"],"truthMode":"canonical","knowledgeScope":"local","contentLevel":"mature"},{"slug":"eos-suit-pairing","title":"Suit Pairing","category":"relationship","fact":"Allowing someone to perform a final exterior suit check is culturally associated with practical trust, though professionals do it routinely without romantic meaning.","triggerTerms":["suit","trust","exterior"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-emergency-contact","title":"Emergency Contact Custom","category":"relationship","fact":"Naming a romantic partner as an emergency contact is considered more serious than many public relationship labels.","triggerTerms":["emergency contact","serious","relationship"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-cabin-access","title":"Cabin Access","category":"dating","fact":"Granting unsupervised cabin access signals trust because private space is scarce, but it does not imply sexual consent or exclusivity.","triggerTerms":["cabin","key","privacy"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-shift-sync","title":"Shift Synchronization","category":"romance","fact":"Couples sometimes request aligned rest shifts; the administrative inconvenience makes the gesture more meaningful than a public announcement.","triggerTerms":["shift","schedule","couple"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-seventeen-hours","title":"Seventeen Missing Hours","category":"history","fact":"Seventeen hours are absent from the certified first-landing record, and official exhibits resume only after First Habitat was already pressurized.","triggerTerms":["seventeen hours","landing","history"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-first-habitat-capacity","title":"First Habitat Capacity","category":"history","fact":"First Habitat was designed for six hundred temporary residents and now supports a permanent district many times larger through additions and reused infrastructure.","triggerTerms":["first habitat","founding","old meridian"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-fixed-sky","title":"The Fixed Sky","category":"culture","fact":"Eos is tidally locked; residents use scheduled interior light cycles and a standard 24-hour clock despite the unmoving red sun and permanent night.","triggerTerms":["sun","time","day","night"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-user-local-clock","title":"Shared Experience Clock","category":"social","fact":"Schedules and plans are experienced in the user’s local clock; nine in the evening means nine in the evening for the user.","triggerTerms":["time","schedule","plan"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-rebreather-rule","title":"Exterior Rebreather Rule","category":"law","fact":"Exposed travel requires certified respiratory and pressure protection even in the temperate band.","triggerTerms":["outside","rebreather","suit"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-storm-closures","title":"Red Storm Closures","category":"law","fact":"Transit and exterior access closures during electrical dust storms are mandatory because rescuers share the risk created by violations.","triggerTerms":["storm","closure","outside"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-artificial-rain","title":"Artificial Rain Tradition","category":"culture","fact":"Public rain cycles in Solace became a social ritual because many residents have never experienced uncontrolled weather.","triggerTerms":["rain","solace","tradition"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-docking-day","title":"Docking Day","category":"culture","fact":"Major passenger arrivals create reunions, departures, shortages, fresh gossip, and unusually crowded port venues.","triggerTerms":["docking","arrival","port"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-foundry-baths","title":"Foundry Bath Etiquette","category":"custom","fact":"The baths are communal and body-comfortable, but staring, photography, and assuming intimacy from shared nudity violate strong local norms.","triggerTerms":["baths","nudity","etiquette"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-quiet-orbit-policy","title":"Quiet Orbit Discretion","category":"privacy","fact":"Quiet Orbit protects guest identity and sound privacy while maintaining clear safety records and refusing to treat discretion as secrecy from consent law.","triggerTerms":["quiet orbit","hotel","privacy"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-signal-public-status","title":"Signal Public Status","category":"politics","fact":"The government acknowledges an unexplained Nightglass transmission but has not classified it as biological, artificial, or dangerous.","triggerTerms":["signal","nightglass","government"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-signal-biology","title":"Signal Biological Response","category":"technology","fact":"Some Solace organisms react before standard receivers register the repeating transmission; the result is verified but unexplained.","triggerTerms":["pollinator","plant","signal"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-black-lake-warmth","title":"Black Lake Warmth","category":"local_knowledge","fact":"A subglacial reservoir beneath Nightglass is warmer than current geothermal models predict.","triggerTerms":["black lake","warm","ice"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-habitat-lyra","title":"Habitat Lyra","category":"history","fact":"Habitat Lyra was evacuated during early expansion and remains officially inactive despite occasional authenticated network traffic.","triggerTerms":["lyra","abandoned habitat","credentials"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-axiom-reserves","title":"Axiom Reserve Dispute","category":"economy","fact":"Local auditors and Axiom use different assumptions to calculate how much reserve capacity independence requires.","triggerTerms":["cost","reserve","independence"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-cargo-scarcity","title":"Import Scarcity","category":"economy","fact":"Imported luxuries can take months to arrive, making remembered preferences, repairs, and locally made gifts socially meaningful.","triggerTerms":["import","gift","cargo"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-local-fabrication","title":"Fabrication Culture","category":"culture","fact":"Repairing and adapting objects is respected across class lines because replacement depends on launch schedules and cargo priority.","triggerTerms":["repair","fabrication","forge"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-low-gravity-health","title":"Low-Gravity Health","category":"technology","fact":"Eos gravity is approximately eighty-three percent of the settlement standard, requiring long-term strength and cardiovascular care.","triggerTerms":["gravity","health","gym"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-departure-question","title":"The Departure Question","category":"dating","fact":"Asking whether someone plans to remain on Eos can become relationship-relevant earlier than exclusivity because transport opportunities are infrequent.","triggerTerms":["leave","stay","departure"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-old-meridian-rent","title":"Old Meridian Housing","category":"economy","fact":"Old Meridian remains the colony’s most affordable dense district because its modules are smaller, older, and socially porous.","triggerTerms":["housing","rent","old meridian"],"truthMode":"canonical","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-ghost-junction-rumor","title":"Ghost Junction Traffic","category":"rumor","fact":"Residents claim the sealed Ghost Junction platform sometimes lights before an unscheduled train passes, but no public timetable confirms service.","triggerTerms":["ghost junction","train","rumor"],"truthMode":"rumor","knowledgeScope":"public","contentLevel":"standard"},{"slug":"eos-aurora-pattern-rumor","title":"Aurora Pattern Rumor","category":"rumor","fact":"Some researchers and musicians believe the aurora repeats structures found in the Nightglass signal; the claimed connection remains disputed.","triggerTerms":["aurora","music","signal"],"truthMode":"rumor","knowledgeScope":"public","contentLevel":"standard"}]$eos_facts$::jsonb);
insert into public.together_world_facts(
  world_id,slug,title,fact_text,category,truth_mode,knowledge_scope,content_level,
  topic_tags,trigger_terms,weight,cooldown_turns,active,metadata
)
select '10000000-0000-4000-8000-000000000012'::uuid,item->>'slug',item->>'title',item->>'fact',item->>'category',item->>'truthMode',
  item->>'knowledgeScope',item->>'contentLevel',array[item->>'category','eos-meridian'],
  array(select jsonb_array_elements_text(item->'triggerTerms')),1,24,true,
  jsonb_build_object('source','eos_meridian_content_v1','closedWorld',true)
from eos_fact_payload cross join lateral jsonb_array_elements(data) item
on conflict(world_id,slug) do update set title=excluded.title,fact_text=excluded.fact_text,category=excluded.category,
  truth_mode=excluded.truth_mode,knowledge_scope=excluded.knowledge_scope,content_level=excluded.content_level,
  topic_tags=excluded.topic_tags,trigger_terms=excluded.trigger_terms,weight=excluded.weight,
  cooldown_turns=excluded.cooldown_turns,active=true,metadata=excluded.metadata,updated_at=now();

create temporary table eos_opportunity_payload(data jsonb) on commit drop;
insert into eos_opportunity_payload values($eos_opportunities$[{"slug":"eos-what-counts-date","topic":"What counts as a real date on Eos?","angle":"Whether a scheduled shared activity feels more intentional than a spontaneous drink.","triggerTerms":["date","plan","real date"],"locationSlugs":["common-room","rain-room"]},{"slug":"eos-staying-or-leaving","topic":"Staying versus leaving","angle":"Whether asking about future transport is practical planning or emotional pressure.","triggerTerms":["leave","stay","transport"],"locationSlugs":["last-window","ascension-terminal"]},{"slug":"eos-shift-sync-meaning","topic":"Synchronizing rest shifts","angle":"When changing a routine for someone becomes a relationship signal.","triggerTerms":["shift","schedule","sleep"],"locationSlugs":["meridian-concourse"]},{"slug":"eos-privacy-scarcity","topic":"Privacy inside a dense colony","angle":"Whether scarce private space makes intimacy more honest or more carefully managed.","triggerTerms":["privacy","room","alone"],"locationSlugs":["quiet-orbit","old-meridian"]},{"slug":"eos-suit-trust","topic":"The meaning of a suit check","angle":"How professional competence and personal trust overlap without becoming the same thing.","triggerTerms":["suit","check","outside"],"locationSlugs":["pressure-school","eventide-overlook"]},{"slug":"eos-independence-cost","topic":"The personal cost of independence","angle":"Which risks feel acceptable when infrastructure and identity are inseparable.","triggerTerms":["independence","charter","axiom"],"locationSlugs":["charter-hall","forge-union-hall"]},{"slug":"eos-artificial-nature","topic":"Whether engineered nature feels real","angle":"How Solace rain, orchards, and water become emotionally authentic through use.","triggerTerms":["rain","nature","garden"],"locationSlugs":["rain-room","orchard-nine"]},{"slug":"eos-departure-lounge","topic":"Why farewells happen at the Last Window","angle":"Whether watching departures makes commitment clearer or harder.","triggerTerms":["goodbye","departure","last window"],"locationSlugs":["last-window"]},{"slug":"eos-recording-intimacy","topic":"Recording and intimate privacy","angle":"Why the colony treats hidden recording as a serious breach of shared safety and personal autonomy.","triggerTerms":["record","camera","private"],"locationSlugs":["quiet-orbit","foundry-baths"]},{"slug":"eos-foundry-bath-culture","topic":"Body comfort at the Foundry Baths","angle":"How communal body comfort differs from invitation, flirting, or sexual availability.","triggerTerms":["bath","naked","body"],"locationSlugs":["foundry-baths"]},{"slug":"eos-seventeen-hours","topic":"The missing landing record","angle":"Whether official omissions protect the colony or undermine every later decision.","triggerTerms":["seventeen hours","founding","landing"],"locationSlugs":["pioneer-memorial","archive-zero"]},{"slug":"eos-signal-meaning","topic":"What the Nightglass signal could mean","angle":"How uncertainty changes when a mystery begins affecting ordinary work and relationships.","triggerTerms":["signal","nightglass","transmission"],"locationSlugs":["listening-station-seven"]},{"slug":"eos-old-vs-new","topic":"Old Meridian and the polished core","angle":"Whether improvement preserves a community or prices out the people who made it livable.","triggerTerms":["old meridian","housing","core"],"locationSlugs":["first-habitat","meridian-core"]},{"slug":"eos-gifts-and-scarcity","topic":"Gifts in an import economy","angle":"When repair, local craft, or a remembered small preference means more than expense.","triggerTerms":["gift","import","make"],"locationSlugs":["atlas-market","salvage-court"]},{"slug":"eos-emergency-contact","topic":"Emergency contacts and seriousness","angle":"Why a practical form can feel more vulnerable than a romantic label.","triggerTerms":["emergency contact","serious","relationship"],"locationSlugs":["meridian-medical-center"]},{"slug":"eos-fixed-sky-time","topic":"Living beneath an unmoving sky","angle":"How people create beginnings, endings, and moods when the exterior light never changes.","triggerTerms":["sun","sky","time"],"locationSlugs":["eventide-overlook","orchard-nine"]},{"slug":"eos-low-gravity-play","topic":"Low gravity and confidence","angle":"Whether altered movement reveals playfulness, vulnerability, or competitiveness.","triggerTerms":["gravity","drift","float"],"locationSlugs":["drift-gym","velvet-gravity"]},{"slug":"eos-colony-gossip","topic":"Anonymity in a small colony","angle":"Whether a population of twenty-four thousand feels private or impossibly interconnected.","triggerTerms":["gossip","everyone knows","small town"],"locationSlugs":["the-airlock-diner","atlas-market"]}]$eos_opportunities$::jsonb);
insert into public.together_dialogue_opportunities(
  world_id,slug,topic,angle,framing,location_id,topic_tags,trigger_terms,content_level,
  interaction_modes,weight,cooldown_turns,active,metadata
)
select '10000000-0000-4000-8000-000000000012'::uuid,item->>'slug',item->>'topic',item->>'angle',
  'Optional only. Let the companion’s identity, work, boundaries, social graph, and relationship stance determine their view. Never force a topic change.',
  location.id,array[item->>'topic','eos-meridian'],array(select jsonb_array_elements_text(item->'triggerTerms')),
  'standard',array['remote','co_present'],1,24,true,
  jsonb_build_object('source','eos_meridian_content_v1','eligibleLocationSlugs',item->'locationSlugs')
from eos_opportunity_payload cross join lateral jsonb_array_elements(data) item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000012'::uuid
  and location.slug=(select value #>> '{}' from jsonb_array_elements(item->'locationSlugs') limit 1)
on conflict(world_id,slug) do update set topic=excluded.topic,angle=excluded.angle,framing=excluded.framing,
  location_id=excluded.location_id,topic_tags=excluded.topic_tags,trigger_terms=excluded.trigger_terms,
  content_level=excluded.content_level,interaction_modes=excluded.interaction_modes,weight=excluded.weight,
  cooldown_turns=excluded.cooldown_turns,active=true,metadata=excluded.metadata,updated_at=now();

create temporary table eos_beat_payload(data jsonb) on commit drop;
insert into eos_beat_payload values($eos_beats$[{"slug":"eos-rain-slowdown","title":"Rain changes the pace","interactionType":"environment","seed":"Artificial rain creates a natural opening to slow down, listen, or remain without demanding a romantic outcome.","affordances":["stay under the canopy","step into the rain","use the quieter moment to ask something real"],"locationSlug":"rain-room","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-last-window-departure","title":"A ship departs","interactionType":"vulnerability","seed":"A visible departure makes future plans briefly harder to keep abstract.","affordances":["watch quietly","ask whether leaving is on their mind","change the subject if the timing feels wrong"],"locationSlug":"last-window","minStage":"friend","contentLevel":"standard"},{"slug":"eos-suit-check","title":"Final suit check","interactionType":"privacy","seed":"A safety check requires careful physical proximity while professional procedure keeps consent and purpose explicit.","affordances":["ask before adjusting a seal","let the companion lead the checklist","keep the interaction practical"],"locationSlug":"pressure-school","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-aurora-silence","title":"Aurora at the edge of night","interactionType":"romance","seed":"The vast night view leaves room for closeness, a personal question, or shared silence.","affordances":["stand closer","ask what they notice first","remain quiet together"],"locationSlug":"eventide-overlook","minStage":"flirting","contentLevel":"romance"},{"slug":"eos-low-gravity-laugh","title":"Low-gravity miscalculation","interactionType":"humor","seed":"A harmless movement mistake creates an opening for teasing or practical help without forcing touch.","affordances":["offer a hand","laugh at yourself","turn it into a friendly challenge"],"locationSlug":"drift-gym","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-market-scarcity","title":"A remembered preference appears","interactionType":"relationship_choice","seed":"A scarce item creates a choice between buying it, remembering it for later, or learning why it matters.","affordances":["ask about the preference","offer it without making the gesture transactional","leave it alone"],"locationSlug":"atlas-market","minStage":"friend","contentLevel":"standard"},{"slug":"eos-communal-table","title":"The last open seats","interactionType":"social","seed":"A crowded communal table brings characters into the same conversation without implying instant intimacy.","affordances":["join the conversation","choose a quieter seat","introduce two people who plausibly know each other"],"locationSlug":"hearth-kitchens","minStage":"stranger","contentLevel":"standard"},{"slug":"eos-bath-boundary","title":"Shared bath etiquette","interactionType":"adult","seed":"The setting allows body comfort and flirtation only through clear present interest, never through assumed availability.","affordances":["keep attention respectful","ask before escalating","let the conversation remain ordinary"],"locationSlug":"foundry-baths","minStage":"flirting","contentLevel":"mature"},{"slug":"eos-storm-shelter","title":"Transit closes","interactionType":"interruption","seed":"A storm changes the plan and creates unhurried shared time without declaring how either person uses it.","affordances":["find food nearby","check what the companion needs","make a new plan together"],"locationSlug":"meridian-concourse","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-archive-contradiction","title":"Two records disagree","interactionType":"discovery","seed":"A small archival contradiction gives both people room to compare interpretations before choosing whether to investigate.","affordances":["ask what feels wrong","check another source","leave the discovery unresolved"],"locationSlug":"archive-zero","minStage":"friend","contentLevel":"standard"},{"slug":"eos-music-pattern","title":"The music repeats the signal","interactionType":"mystery","seed":"A familiar musical phrase unexpectedly matches a technical pattern, creating an opening rather than proving a theory.","affordances":["ask whether it was intentional","record the moment","enjoy the song without investigating"],"locationSlug":"static-garden","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-private-room-choice","title":"Privacy becomes available","interactionType":"privacy","seed":"A genuinely private room creates an opportunity for honesty or intimacy but never defines what happens there.","affordances":["talk without being overheard","confirm what each person wants","choose not to enter"],"locationSlug":"quiet-orbit","minStage":"dating","contentLevel":"mature"},{"slug":"eos-orchard-fruit","title":"A ripe fruit is ready","interactionType":"flirt","seed":"An ordinary orchard task can become playful or tender through the people involved rather than a scripted gesture.","affordances":["share the fruit","turn picking into a small competition","keep walking"],"locationSlug":"orchard-nine","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-black-lake-sound","title":"Something moves below","interactionType":"mystery","seed":"A sound beneath the dark water interrupts the scene and allows caution, curiosity, or leaving.","affordances":["check instruments","step back together","decide this is not the moment"],"locationSlug":"black-lake","minStage":"friend","contentLevel":"standard"},{"slug":"eos-club-gravity-shift","title":"Gravity changes with the set","interactionType":"flirt","seed":"The dance floor changes weight gradually, offering play and closeness only if both people lean into it.","affordances":["dance independently","offer a hand","move to a quiet booth"],"locationSlug":"velvet-gravity","minStage":"flirting","contentLevel":"romance"},{"slug":"eos-cargo-delay","title":"A shipment is delayed","interactionType":"mistake","seed":"A delayed import disrupts a plan and invites improvisation without treating inconvenience as catastrophe.","affordances":["find a local substitute","ask who is affected","make the altered plan part of the date"],"locationSlug":"cargo-exchange","minStage":"acquaintance","contentLevel":"standard"},{"slug":"eos-charter-disagreement","title":"A public argument follows them out","interactionType":"conflict","seed":"A civic disagreement gives a character room to state a real view without forcing the user to agree.","affordances":["ask what the issue costs personally","disagree respectfully","save politics for later"],"locationSlug":"charter-hall","minStage":"friend","contentLevel":"standard"},{"slug":"eos-home-access","title":"A cabin invitation is possible","interactionType":"relationship_choice","seed":"The companion may consider offering private access, withholding it, or discussing what it would mean; the beat does not grant entry.","affordances":["ask rather than assume","let the companion define the boundary","choose a public alternative"],"locationSlug":null,"minStage":"dating","contentLevel":"romance"}]$eos_beats$::jsonb);
insert into public.together_scene_interaction_beats(
  world_id,slug,title,location_id,interaction_type,seed,affordances,topic_tags,character_tags,
  min_relationship_stage,content_level,min_spice_level,interaction_modes,co_present_required,
  required_participant_count,maximum_participant_count,dayparts,activity_tags,weight,cooldown_hours,active,metadata
)
select '10000000-0000-4000-8000-000000000012'::uuid,item->>'slug',item->>'title',location.id,item->>'interactionType',item->>'seed',
  item->'affordances',array[item->>'interactionType','eos-meridian'],'{}'::text[],item->>'minStage',item->>'contentLevel',
  case when item->>'contentLevel' in('mature','explicit') then 2 else null end,array['co_present','date','plan'],true,1,2,
  array['morning','afternoon','evening','late_night'],array[item->>'interactionType'],1,
  case when item->>'interactionType' in('mystery','relationship_choice') then 72 else 24 end,true,
  jsonb_build_object('source','eos_meridian_content_v1','neverDeclareUserAction',true,'neverMutateRelationshipDirectly',true)
from eos_beat_payload cross join lateral jsonb_array_elements(data) item
left join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000012'::uuid and location.slug=item->>'locationSlug'
on conflict(world_id,slug) do update set title=excluded.title,location_id=excluded.location_id,
  interaction_type=excluded.interaction_type,seed=excluded.seed,affordances=excluded.affordances,
  topic_tags=excluded.topic_tags,min_relationship_stage=excluded.min_relationship_stage,
  content_level=excluded.content_level,min_spice_level=excluded.min_spice_level,
  interaction_modes=excluded.interaction_modes,co_present_required=excluded.co_present_required,
  cooldown_hours=excluded.cooldown_hours,active=true,metadata=excluded.metadata,updated_at=now();

create temporary table eos_date_payload(data jsonb) on commit drop;
insert into eos_date_payload values($eos_dates$[{"slug":"eos-rain-room-after-hours","title":"Rain After Hours","locationSlug":"rain-room","setup":"A reserved artificial-rain cycle leaves the conservatory warm, quiet, and unhurried.","tone":"romantic","season":"permanent twilight"},{"slug":"eos-orchard-nine-walk","title":"Orchard Nine Walk","locationSlug":"orchard-nine","setup":"A slow walk among productive trees makes ordinary future questions feel unusually close.","tone":"gentle","season":"permanent twilight"},{"slug":"eos-last-window-departure","title":"Drinks at the Last Window","locationSlug":"last-window","setup":"Cocktails and departing spacecraft turn a sophisticated evening toward the question of staying.","tone":"intimate","season":"permanent twilight"},{"slug":"eos-eventide-aurora","title":"Aurora at Eventide","locationSlug":"eventide-overlook","setup":"A carefully prepared exterior date puts the permanent night and shared trust in full view.","tone":"adventurous","season":"permanent twilight"},{"slug":"eos-foundry-baths-recovery","title":"Foundry Baths","locationSlug":"foundry-baths","setup":"Geothermal pools offer warmth, body comfort, and conversation after a hard shift.","tone":"sensual","season":"permanent twilight"},{"slug":"eos-low-g-dance","title":"Low-G Dance Night","locationSlug":"velvet-gravity","setup":"Music and controlled low gravity create a playful evening where both people choose the pace.","tone":"playful","season":"permanent twilight"},{"slug":"eos-canopy-dinner","title":"Dinner in the Canopy","locationSlug":"the-canopy","setup":"A small table among greenhouse rafters makes the engineered landscape feel private.","tone":"romantic","season":"permanent twilight"},{"slug":"eos-black-sky-observatory","title":"Black Sky Viewing","locationSlug":"nightglass-observatory","setup":"Dimmed colony lights reveal the aurora and stars while researchers work quietly nearby.","tone":"reflective","season":"permanent twilight"},{"slug":"eos-cargo-market-challenge","title":"Cargo Exchange Challenge","locationSlug":"cargo-exchange","setup":"Each person chooses one surprising local or imported ingredient for a shared meal.","tone":"playful","season":"permanent twilight"},{"slug":"eos-static-garden-show","title":"Static Garden Show","locationSlug":"static-garden","setup":"A live set in the old power room offers music, crowd energy, and a quieter corridor afterward.","tone":"lively","season":"permanent twilight"},{"slug":"eos-solace-long-table","title":"The Long Table","locationSlug":"hearth-kitchens","setup":"A communal dinner tests whether the pair feels more or less intimate around familiar faces.","tone":"social","season":"permanent twilight"},{"slug":"eos-pioneer-memorial-walk","title":"Founding Stories","locationSlug":"pioneer-memorial","setup":"A museum visit becomes a conversation about which histories people inherit and revise.","tone":"thoughtful","season":"permanent twilight"},{"slug":"eos-drift-gym-session","title":"Low-Gravity Session","locationSlug":"drift-gym","setup":"A private training bay turns unfamiliar movement into trust, laughter, and friendly competition.","tone":"playful","season":"permanent twilight"},{"slug":"eos-thermal-garden-night","title":"Thermal Garden at Night","locationSlug":"thermal-garden","setup":"Dark foliage, geothermal mist, and aurora glass create a quieter side of Nightglass.","tone":"intimate","season":"permanent twilight"},{"slug":"eos-atlas-market-meal","title":"Atlas Market Meal","locationSlug":"atlas-market","setup":"Browsing scarce imports and local food reveals preferences that biography never would.","tone":"casual","season":"permanent twilight"},{"slug":"eos-quiet-orbit-retreat","title":"Quiet Orbit Retreat","locationSlug":"quiet-orbit","setup":"A discreet suite offers privacy for conversation or intimacy only at the pace both people choose.","tone":"sensual","season":"permanent twilight"},{"slug":"eos-first-habitat-history","title":"First Habitat Walk","locationSlug":"first-habitat","setup":"Old corridors and lived-in homes make colony history personal instead of monumental.","tone":"reflective","season":"permanent twilight"},{"slug":"eos-common-room-last-table","title":"The Last Table","locationSlug":"common-room","setup":"A late meal after the crowd thins turns an ordinary public room into a repeatable shared place.","tone":"grounded","season":"permanent twilight"}]$eos_dates$::jsonb);
insert into public.together_date_templates(
  id,name,slug,world_id,location_id,description,hero_asset_key,phases,unlock_rules,entitlement_key,active,metadata
)
select ('4f000000-0000-4000-8012-'||lpad(ordinality::text,12,'0'))::uuid,item->>'title',item->>'slug',
  '10000000-0000-4000-8000-000000000012'::uuid,location.id,item->>'setup','eos-meridian-hero',
  jsonb_build_array(
    jsonb_build_object('id','arrival','title','Arrive','choices',jsonb_build_array(
      jsonb_build_object('id','lean-in','label','Lean into the plan'),jsonb_build_object('id','take-it-in','label','Take in the place'))),
    jsonb_build_object('id','conversation','title','Settle in','choices',jsonb_build_array(
      jsonb_build_object('id','ask-real','label','Ask something real'),jsonb_build_object('id','follow-mood','label','Follow the mood'))),
    jsonb_build_object('id','turn','title','Something changes','choices',jsonb_build_array(
      jsonb_build_object('id','stay','label','Stay a little longer'),jsonb_build_object('id','change-pace','label','Change the pace'))),
    jsonb_build_object('id','resolution','title','What you keep','choices','[]'::jsonb)),
  '{"familiarity":12,"trust":10,"allowed_stages":["acquaintance","friend","flirting","dating","exclusive","long_term"]}'::jsonb,
  'worlds.standard',true,jsonb_build_object('source','eos_meridian_content_v1','season',item->>'season','tone',item->>'tone')
from eos_date_payload cross join lateral jsonb_array_elements(data) with ordinality payload(item,ordinality)
join public.together_locations location on location.world_id='10000000-0000-4000-8000-000000000012'::uuid and location.slug=item->>'locationSlug'
on conflict(id) do update set name=excluded.name,slug=excluded.slug,world_id=excluded.world_id,
  location_id=excluded.location_id,description=excluded.description,hero_asset_key=excluded.hero_asset_key,
  phases=excluded.phases,unlock_rules=excluded.unlock_rules,entitlement_key=excluded.entitlement_key,
  active=true,metadata=excluded.metadata,updated_at=now();

update public.together_worlds set metadata=metadata||jsonb_build_object(
  'residentCompanionCount',47,'residentRosterStatus','ready','residentScheduleStatus','authored_weekly_v1',
  'socialGraphStatus','authored_v1','recurringEventCount',8,'storyArcCount',6,
  'worldFactCount',30,'dialogueOpportunityCount',18,
  'interactionBeatCount',18,'nativeDateCount',18,
  'residentPortraitStatus','primary_portraits_ready','mappedResidentPortraitCount',47
),updated_at=now() where id='10000000-0000-4000-8000-000000000012'::uuid;

do $$
declare schedule_count int;complete_days int;invalid_locations int;edge_count int;place_profile_count int;
  event_count int;story_count int;fact_count int;opportunity_count int;beat_count int;date_count int;
begin
  select count(*) into schedule_count from public.together_schedule_templates where character_version_id::text like '25000000-0000-4000-8012-%';
  select count(*) into complete_days from(
    select character_version_id,day_of_week from public.together_schedule_templates
    where character_version_id::text like '25000000-0000-4000-8012-%'
    group by character_version_id,day_of_week having count(*)=6 and min(start_minute)=0 and max(end_minute)=1440
  ) days;
  select count(*) into invalid_locations from public.together_schedule_templates schedule
    left join public.together_locations location on location.id=schedule.location_id
    where schedule.character_version_id::text like '25000000-0000-4000-8012-%'
      and schedule.location_id is not null and location.world_id is distinct from '10000000-0000-4000-8000-000000000012'::uuid;
  select count(*) into edge_count from public.together_character_relationship_edges where world_id='10000000-0000-4000-8000-000000000012'::uuid;
  select count(*) into place_profile_count from public.together_character_place_profiles where character_version_id::text like '25000000-0000-4000-8012-%';
  select count(*) into event_count from public.together_event_templates where world_id='10000000-0000-4000-8000-000000000012'::uuid and active;
  select count(*) into story_count from public.together_story_arc_templates where specific_world_id='10000000-0000-4000-8000-000000000012'::uuid and active;
  select count(*) into fact_count from public.together_world_facts where world_id='10000000-0000-4000-8000-000000000012'::uuid and active;
  select count(*) into opportunity_count from public.together_dialogue_opportunities where world_id='10000000-0000-4000-8000-000000000012'::uuid and active;
  select count(*) into beat_count from public.together_scene_interaction_beats where world_id='10000000-0000-4000-8000-000000000012'::uuid and active;
  select count(*) into date_count from public.together_date_templates where world_id='10000000-0000-4000-8000-000000000012'::uuid and active;
  if schedule_count<>1974 or complete_days<>329 or invalid_locations<>0
    or edge_count<180 or place_profile_count<>47 or event_count<>8
    or story_count<>6 or fact_count<>30 or opportunity_count<>18
    or beat_count<>18 or date_count<>18 then
    raise exception 'Eos simulation validation failed: schedules %, days %, invalid %, edges %, profiles %, events %, stories %, facts %, opportunities %, beats %, dates %',
      schedule_count,complete_days,invalid_locations,edge_count,place_profile_count,event_count,story_count,fact_count,opportunity_count,beat_count,date_count;
  end if;
end $$;
commit;
